    "of_two_vectors_of": "Dari dua vektor berisi 2, 3, atau 4 bilangan, diketik 1, 2, 3: hasil kali titik, hasil kali silang, panjang, dan sudut di antara keduanya, proyeksi u pada v, dan u berpanjang 1.",
    "complex_number": "Bilangan kompleks",
    "work_out_complex_number": "Hitung bilangan kompleks: (2 + 3i)(1 – i), sqrt(-4), e^(iπ), atau 2∠30 dalam bentuk polar. Bagian real dan imajinernya, panjang, sudut, dan konjugatnya, serta bentuk r e^(iθ)-nya.",
    "roots_of_complex_number": "Akar bilangan kompleks",
    "n_n_th_roots": "n akar pangkat n dari bilangan kompleks: akar pangkat tiga dari 1, akar pangkat empat dari -16.",
    "polynomial_roots": "Akar polinomial",
    "every_root_of_polynomial_2": "Semua akar polinomial berkoefisien kompleks, berpangkat berapa pun sampai 30: diketik, x^2 + (1 + i)x + 2i, atau koefisiennya dari pangkat tertinggi, 1, 1 + i, 2i.",
    "ac_impedance": "Impedansi AC",
    "impedance_of_resistor_coil": "Impedansi resistor, kumparan, dan kapasitor pada suatu frekuensi, seri atau paralel: Z sebagai a + bi, besar dan fasenya, reaktansi kumparan dan kapasitor, serta frekuensi saat keduanya saling meniadakan. Boleh tanpa R, L, atau C; nilai boleh berawalan, 4.7k, 10m, 100µ, atau 1e-6.",
    "f_hz": "f, Hz",
    "circuit": "Rangkaian",
    "parallel": "Paralel",
    "bases": "Basis bilangan",
    "whole_numbers_as_computer": "Bilangan bulat seperti yang disimpan komputer, dalam 8, 16, 32, 64, atau 128 bit: desimal, heksadesimal 0x, biner 0b, atau oktal 0o, dengan + – × ÷ mod AND OR XOR NOT NAND NOR XNOR, &lt;&lt; &gt;&gt;, serta ROL ROR, yang memutar bit. Setiap hasil dalam semua basis, beserta byte-nya big-endian dan little-endian, dan yang ditukar.",
    "number": "Bilangan",
    "0xff_and_0b1010": "0xFF AND 0b1010",
    "bits": "Bit",
    "bits_of_whole_number": "Bit-bit suatu bilangan bulat, masing-masing bisa dibalik dengan klik; berapa yang bernilai 1, angka 0 sebelum dan sesudahnya, serta bit 1 tertinggi dan terendah. Jika kosong, nilainya 0, untuk menyusun bilangan dengan klik.",
    "truth_table": "Tabel kebenaran",
    "function_of_logic_of": "Fungsi logika hingga 8 variabel: A AND NOT B, AB + C', dua huruf berdampingan berarti AND dan ' untuk NOT, (A + B)(A' + C), A XOR B, !a | b & c, NAND, NOR, dan XNOR; atau dari baris-barisnya, Σm(1, 3, 5) + d(7), d untuk yang boleh bernilai apa saja, atau ΠM(0, 2). F(A, B, C) = di depannya menentukan urutan variabel. Tabel kebenaran, minterm dan maxterm-nya, serta bentuk paling sederhananya, menurut Quine-McCluskey, sebagai jumlah hasil kali dan hasil kali jumlah; untuk 2 sampai 4 variabel, peta Karnaugh-nya digambar, dengan setiap hasil kali dilingkari.",
    "expression": "Ekspresi",
    "ab_c_bc": "AB + A'C + BC",
    "gray_code": "Kode Gray",
    "whole_number_in_gray": "Bilangan bulat dalam kode Gray, setiap bilangan berikutnya hanya berbeda satu bit, seperti piringan encoder ditandai agar tidak pernah salah membaca langkah; atau bilangan dari suatu kode Gray, diketik sebagai 0b0111. Digambar: kode-kode di sekitarnya, dengan bit yang berubah ke masing-masing ditandai.",
    "find": "Cari",
    "gray_code_2": "Kode Gray-nya",
