    "ieee_754": "IEEE 754",
    "number_as_computer_keeps": "Bilangan seperti yang disimpan komputer: double 64 bit dan float 32 bit, dalam heksadesimal; tanda, eksponen, dan fraksinya; bilangan sebenarnya, sampai digit terakhirnya, dan jaraknya ke bilangan berikutnya. Atau bit-bitnya, 0x3FB999999999999A, untuk mendapatkan bilangannya.",
    "any_base": "Basis apa pun",
