    "f_ma_inclined_plane": "F = ma, bidang miring dengan gesekan, massa pada katrol, tumbukan, impuls, energi kinetik dan potensial, usaha dan daya, torsi dan tuas, gravitasi dan jari-jari Schwarzschild, pegas, hambatan dan kecepatan terminal, hukum Coulomb, gaya magnet, medan kawat, solenoida, atau kumparan melingkar, dan induksi.",
    "electronics": "Elektronika",
    "resistor_colour_code_both": "Kode warna resistor dua arah, kode SMD dan EIA-96, komponen seri dan paralel, hukum Ohm, resistansi kawat dan AWG-nya, pembagi tegangan dan Thévenin, jembatan Wheatstone, resistor LED, kapasitor, RC dan RL, filter orde pertama dan kedua, pelat sejajar, transformator dan AC, daya tiga fase, impedansi dan resonansi R, L, dan C, biaya listrik, daya tahan baterai; dioda dan penyearah dengan riaknya; transistor sebagai sakelar dan bias, MOSFET, Zener, LM317, op-amp, dan 555; dBm, dBV, dan dBµV, serta penguatan dalam dB. Nilai komponen seperti tertulis: 4.7k, 4k7, 100n; resistor yang dibeli, dari E12.",
    "v_f_standing_waves": "v = fλ, gelombang berdiri pada dawai dan pipa, pelayangan, lensa dan cermin, persamaan pembuat lensa, pembiasan dan sudut kritis, interferensi melalui dua celah atau kisi, satu celah dan resolusi lensa, polarisasi, efek Doppler bunyi dan cahaya, cahaya dan foton, dan bunyi dalam desibel.",
    "matter": "Zat",
    "heat_q_mc_t": "Kalor: Q = mcΔT dari tiga mana pun, kalor laten, pencampuran, pemuaian, konduksi, radiasi, pendinginan Newton, titik embun, kecepatan molekul gas, gas ideal isotermal, isobarik, isokhorik, atau adiabatik, dan mesin kalor. Zat padat: tegangan dan regangan. Fluida: massa jenis, tekanan, tekanan pada kedalaman, gaya apung, aliran dalam pipa, bilangan Reynolds dengan gesekan pipa, dan hukum Stokes.",
    "modern": "Modern",
    "e_mc_binding_energy": "E = mc², energi ikat, nilai Q suatu reaksi, efek fotolistrik, panjang gelombang de Broglie, prinsip ketidakpastian, partikel dalam kotak, hamburan Compton, terobosan, relativitas khusus, garis spektrum hidrogen dan orbit Bohr, dan peluruhan radioaktif.",
    "biology": "Biologi",
    "genetics_from_punnett_squares": "Genetika, dari kotak Punnett sampai peta gen dan risiko genetik; DNA dan RNA, diterjemahkan, dijajarkan, dengan primer, pemandu CRISPR, dan gel; protein dan enzim; pengenceran, hitungan, dan qPCR laboratorium; sel; kesehatan; serta ekologi dan evolusi. Klik bilangan untuk memasukkannya.",
    "close_biology": "Tutup biologi",
    "genetics": "Genetika",
    "punnett_squares_of_up": "Kotak Punnett sampai enam gen, digambar, dan untuk X; Hardy–Weinberg, dari p, dari cacah dengan uji χ²-nya, atau dari sifat resesif; χ² suatu persilangan; peta gen dua atau tiga gen, kromosom digambar; peluang keturunan; heritabilitas, menurut persamaan pemulia; epistasis dan rasio yang cocok; risiko genetik, keluarga digambar sebagai silsilah; dan golongan darah.",
    "sequence_s_length_bases": "Panjang urutan, basa, GC sepanjang urutan dan massa, dengan komplemen dan komplemen baliknya; terjemahan dalam enam bingkai dan kerangka baca terbuka, digambar; roda kodon; T<sub>m</sub> primer menurut tetangga terdekat, kurva lelehnya digambar; DNA dan RNA menurut A<sub>260</sub> dan kemurniannya; massa, mol, dan salinan; ligasi, plasmid digambar; digesti restriksi pada gel; salinan PCR, siklus demi siklus; penjajaran, global dan lokal, dengan dot plot; pemandu CRISPR; motif dari kode IUPAC; primer untuk mutagenesis dan perakitan Gibson; serta genom dan salinannya.",
    "protein_s_mass_pi": "Massa protein, pI, muatan, ekstingsi, dan hidropati, digambar; kedua puluh asam amino, titrasi masing-masing digambar; konsentrasi protein menurut A<sub>280</sub> atau kurva standar; kinetika enzim, dari V<sub>max</sub> dan K<sub>m</sub> atau dicocokkan ke titik-titik, dengan inhibitor dan plot Lineweaver–Burk; pengikatan menurut Hill; dosis–respons, IC<sub>50</sub>-nya dicocokkan; dan tabel pemurnian.",
    "lab": "Laboratorium",
    "c_v_c_v": "C₁V₁ = C₂V₂ dan pengenceran bertingkat, tabungnya digambar; membuat larutan, dari molaritas, rumus, persen, atau stok; menghitung sel; pertumbuhan dan penggandaan, dan OD<sub>600</sub>; koloni dan CFU/mL; RPM dan g sentrifuge; master mix PCR; qPCR menurut ΔΔCt dan kurva standarnya; rata-rata ± 2 SE dengan batang galat; R<sub>f</sub> kromatografi; mikroskop; ukuran dari gel; efisiensi transformasi; menyemai pelat; MOI; radioisotop; dan buffer.",
    "water_potential_osmolarity_and": "Potensial air, osmolaritas, dan tonisitas, sel darah merah digambar; luas permukaan terhadap volume; Q₁₀; difusi menurut Fick; potensial membran menurut Nernst dan Goldman; energi bebas; curah jantung dan tekanan darah, digambar; serta respirasi, ATP-nya, dan hasil bagi respirasi.",
    "health": "Kesehatan",
    "diagnostic_tests_their_sensitivity": "Uji diagnostik, sensitivitas, spesifisitas, dan nilai prediktifnya, seribu orang digambar; rasio risiko dan odds dengan intervalnya, dan jumlah yang perlu diobati; epidemi menurut SIR dan kekebalan kelompok; oksigen dan hemoglobin, pergeseran Bohr digambar; potensial aksi menurut Hodgkin dan Huxley; ginjal, eGFR, dan klirens; IMT dan energi; serta kadar obat selama pemberian dosis. Untuk belajar, bukan untuk perawatan.",
    "ecology": "Ekologi",
    "population_growth_exponential_and": "Pertumbuhan populasi, eksponensial dan logistik; pemangsa dan mangsa menurut Lotka dan Volterra; tandai dan tangkap ulang; keanekaragaman menurut Simpson dan Shannon; tabel kehidupan dan kelangsungan hidup; piramida energi; produktivitas primer; seleksi alam dan hanyutan genetik, generasi demi generasi; matriks Leslie; kompetisi; spesies, luas, dan rarefaksi; pohon menurut UPGMA dan neighbour joining; dan jam molekuler.",
    "opens_card_of_physics": "Membuka kartu panel Fisika yang menghitung ini, dengan yang Anda ketik di dalamnya: di sana, huruf mana pun dapat dicari dari yang lain.",
    "opens_card_of_finance": "Membuka kartu tab Keuangan pada Selesaikan yang menghitung ini, dengan yang Anda ketik di dalamnya, dan hasil tambahannya.",
    "opens_card_of_biology": "Membuka kartu panel Biologi yang menghitung ini, dengan yang Anda ketik di dalamnya, dan menggambarnya.",
    "elastic": "Lenting",
    "they_bounce_apart_as": "Keduanya saling memantul, seperti bola biliar, dan tidak ada energi kinetik yang hilang.",
    "they_go_on_as": "Keduanya bergerak sebagai satu: momentum tetap, dan energi kinetik hilang sebanyak mungkin.",
    "pop_out": "Pisahkan",
    "panel_as_big_as": "Panel sebesar halaman, kartu-kartunya dalam daftar dengan yang terbuka di sampingnya; di ekstensi, di jendela tersendiri.",
    "pop_in": "Gabungkan",
    "panel_back_in_calculator": "Panel kembali ke kalkulator.",
    "periodic_table_as_big": "Tabel periodik sebesar halaman, tiap unsur dengan nomor, nama, dan massanya; di ekstensi, di jendela tersendiri.",
