    "table_back_in_calculator": "Tabel kembali ke kalkulator.",
    "all_118_elements_point": "Semua 118 unsur. Arahkan ke salah satunya untuk melihatnya di atas tabel, klik untuk semua yang diketahui tentangnya dan atomnya; tombol panah berpindah dari satu ke berikutnya.",
    "molar_mass_of_formula_2": "Massa molar suatu rumus dan bagian tiap unsur di dalamnya; gram, mol, dan partikel; serta rumus empiris dan molekul suatu komposisi.",
    "equation_balanced_with_kind": "Persamaan yang disetarakan, dengan jenisnya dan yang dioksidasi dan direduksi; jumlah suatu reaksi, pereaksi pembatas, dan persen rendemennya; lembar latihan; kalor, q = mcΔT; dan waktu paruh.",
    "solutions": "Larutan",
    "molarity_dilution_freezing_and": "Molaritas, pengenceran, titik beku dan titik didih larutan, pH, pOH, [H⁺], dan [OH⁻], asam dan basa lemah, buffer, dan yang larut dalam air.",
    "common_ions_monatomic_and": "Ion umum, monoatomik dan poliatomik: muatan dan massa molar masing-masing, warnanya dalam air dan dalam nyala api; nama suatu rumus dan rumus suatu nama; dan bilangan oksidasi.",
    "ideal_gas_law_pv": "Hukum gas ideal, PV = nRT, dengan massa dan massa jenis gas; hukum gas gabungan; tekanan parsial; gas yang ditampung di atas air; volume gas-gas suatu reaksi; efusi; udara menurut ketinggian; dan kecepatan bunyi.",
