    "how_strongly_pulls_electrons": "Seberapa kuat ia menarik elektron dalam ikatan, pada skala Pauling: biru untuk sedikit, merah untuk banyak. Fluorin menarik paling kuat, 3.98.",
    "slide_and_each_element": "Geser dan tiap unsur berwujud padat, cair, atau gas sesuai suhu itu, pada 1 atm, dari titik leleh dan didihnya. Klik suhunya untuk kembali ke 20 °C.",
