    "how_strongly_atom_pulls": "Seberapa kuat atomnya menarik elektron ikatan, pada skala Pauling, dari 0.79 untuk sesium sampai 3.98 untuk fluorin. Gas mulia yang jarang berikatan tidak punya nilai.",
