    "energy_to_warm_gram": "Energi untuk menaikkan suhu satu gram unsur itu sebesar 1 K, pada 25 °C: q = mcΔT. Tidak terukur untuk kebanyakan unsur radioaktif.",
    "when_was_found_by": "Kapan ditemukan, oleh siapa, dan siapa yang pertama kali membuatnya murni.",
    "isotopes": "Isotop",
    "stable_isotopes_commonest_first": "Isotop stabilnya, yang paling umum lebih dulu; jika tidak ada yang stabil, yang ditemukan di alam, atau yang paling lama bertahan beserta waktu paruhnya.",
    "where_name_comes_from": "Asal usul namanya, dan bagaimana ia ditemukan.",
