    "what_used_for": "Untuk apa ia digunakan.",
    "covalent_radius": "Jari-jari kovalen",
    "half_length_of_single": "Setengah panjang ikatan tunggal antara dua atomnya, dalam pikometer: seberapa besar atomnya dalam molekul, lebih kecil dari jari-jari van der Waals-nya.",
    "heat_of_fusion": "Kalor peleburan",
