    "thermal_conductivity": "Konduktivitas termal",
    "how_well_heat_flows": "Seberapa baik kalor mengalir melaluinya: watt melalui satu meter unsur itu untuk tiap kelvin di antara ujung-ujungnya, melintasi satu meter persegi. Perak dan tembaga paling besar, gas paling kecil.",
    "electrical_resistivity": "Resistivitas listrik",
    "how_much_resists_current": "Seberapa besar ia menahan arus, pada 20 °C: R = ρL/A. Kecil untuk logam, 1.6 × 10⁻⁸ Ω·m untuk perak yang terkecil; sangat besar untuk isolator seperti belerang.",
    "mohs_hardness": "Kekerasan Mohs",
