    "magnetism": "Magnetisme",
    "how_acts_in_magnetic": "Bagaimana ia bersikap dalam medan magnet: feromagnetik, seperti besi, magnet itu sendiri; paramagnetik, ditarik lemah; diamagnetik, ditolak lemah; antiferromagnetik, magnetisme atomnya saling meniadakan.",
    "crystal_structure": "Struktur kristal",
    "how_atoms_packed_in": "Bagaimana atomnya tersusun dalam zat padat, pada suhu kamar. Digambar di bawahnya, sel satuannya, kotak terkecil yang berulang, atau untuk yang heksagonal berupa prisma dari 3; atomnya dihitung menurut bagiannya: satu di sudut dibagi 8 kotak, atau 6 prisma, di sisi dibagi 2. Bola abu-abu: hanya kisinya, banyak atom di tiap titik.",
    "abundance_in_crust": "Kelimpahan di kerak bumi",
    "how_much_of_earth": "Seberapa banyak ia ada di kerak bumi, dalam mg/kg, bagian per juta menurut massa: oksigen hampir setengahnya, lalu silikon. Hanya jejak: beberapa atom sekaligus, dibuat dalam bijih uranium dan torium; sintetis: hanya dibuat di laboratorium.",
    "appearance": "Penampilan",
    "what_looks_like_pure": "Tampilannya, murni, pada suhu kamar.",
    "light_of_atoms_as": "Cahaya atomnya sebagai gas, dari ungu pada 380 nm sampai merah pada 750: absorpsi, cahaya putih yang ditembakkan melaluinya, garis gelap di spektrum pelangi tempat warna terserap; emisi, saat dipanaskan atau dalam percikan, warna yang sama saja, terang di atas latar hitam. Tiap unsur punya garis sendiri, seperti sidik jari: itulah sebabnya helium ditemukan di Matahari sebelum di Bumi. Garis terkuatnya, seperti daftar NIST, makin kuat makin lebar; untuk unsur yang atomnya tidak punya di sini, garis ionnya. Klik: yang lain.",
    "alkali_metal": "Logam alkali",
    "group_1_but_hydrogen": "Golongan 1 selain hidrogen: logam lunak yang bereaksi hebat dengan air, menghasilkan hidroksida dan hidrogen. Satu elektron terluar, dilepas sebagai ion 1+.",
    "alkaline_earth_metal": "Logam alkali tanah",
