    "transition_metal": "Logam transisi",
    "groups_3_to_12": "Golongan 3 sampai 12, mengisi subkulit d: logam keras, dengan banyak bilangan oksidasi dan senyawa berwarna; katalis yang baik.",
    "post_transition_metal": "Logam pasca-transisi",
    "metals_after_transition_metals": "Logam setelah logam transisi: lebih lunak, titik lelehnya lebih rendah, sebagian dengan oksida yang bersifat asam sekaligus basa.",
    "metalloid": "Metaloid",
    "between_metals_and_nonmetals": "Di antara logam dan nonlogam: semikonduktor, seperti silikon dan germanium.",
    "nonmetal": "Nonlogam",
    "poor_conductors_of_heat": "Penghantar kalor dan listrik yang buruk, berupa gas atau zat padat rapuh, yang menerima atau berbagi elektron dalam senyawanya.",
    "halogen": "Halogen",
    "group_17_reactive_nonmetals": "Golongan 17: nonlogam reaktif, kurang satu elektron untuk kulit penuh, diambil sebagai ion 1−; dengan logam membentuk garam.",
    "noble_gas": "Gas mulia",
