    "opens_parenthetical_expression_expressions": "[(] Membuka ekspresi dalam kurung. Ekspresi dapat bersarang. Mengkliknya memunculkan cincin di sekitar tombol untuk memberi tahu bahwa ekspresi dalam kurung masih aktif (sampai semua ekspresi ditutup dengan kurung tutup atau tanda sama dengan).",
    "number_right_before_parenthesis": "Angka tepat sebelum kurung dikalikan: 5 ( 2 + 3 ) adalah 5 × (2 + 3).",
    "closes_parenthetical_expression_ring": "[)] Menutup ekspresi dalam kurung. Cincin di sekitar tombol kurung ( akan tetap ada sampai semua ekspresi ditutup dengan tombol ini atau setelah mengklik tanda sama dengan.",
    "calculates_percentages_adds_markups": "[%] Menghitung persentase, menambah markup, dan mengurangi diskon. Sendirian ia membagi nilai dengan 100: 50 % menghasilkan 0.5. Misalnya, untuk menghitung 8% dari 500, masukkan 8 % × 500 = yang menghasilkan 40.",
