    "h_n_returns_random": "[h, n] Menghasilkan bilangan acak antara 0 dan 1.",
    "v_click_to_clear": "[v] Klik untuk menghapus memori.",
    "b_click_to_add": "[b] Klik untuk menambahkan angka yang ditampilkan ke angka dalam memori. Jika tidak ada angka dalam memori, klik untuk menyimpan angka yang ditampilkan ke memori. Layar menampilkan M+ sesaat.",
    "n_click_to_subtract": "[n] Klik untuk mengurangkan angka yang ditampilkan dari angka dalam memori. Jika tidak ada angka dalam memori, klik untuk menyimpan angka yang ditampilkan sebagai pengurangan dari nol dalam memori. Layar menampilkan M– sesaat.",
    "m_click_to_replace": "[m] Klik untuk menggantikan angka yang ditampilkan dengan angka dalam memori.",
