    "shift_m_on": "[Shift+M] Pada lapisan",
    "remainder_after_dividing_17": ". Sisa pembagian: 17 mod 5 = 2. Ia mengikuti tanda bilangan kedua (-7 mod 3 = 2), dan bekerja dengan desimal (7.5 mod 2 = 1.5).",
    "shift_q_on": "[Shift+Q] Pada lapisan",
